package school.magiccodex.client;
import org.junit.jupiter.api.Test;import org.junit.jupiter.api.io.TempDir;import java.nio.file.*;import static org.junit.jupiter.api.Assertions.*;
class NormalSpellPresetsTest{
 @TempDir Path dir;
 @Test void oldSlotsAndBindingsRemainPresetOneAndSecondIsExistingDefault()throws Exception{var old=new SpellKeySettings();old.assign(49,"flight");old.assign(50,"rainbow_collar");old.swapOrder(0,1);old.save(dir.resolve("key-settings.yml"));byte[] original=Files.readAllBytes(dir.resolve("key-settings.yml"));var p=new NormalSpellPresets(dir);assertTrue(old.sameAs(p.load()));assertEquals(0,SpellKeySettings.load(p.path(2)).count());p.confirmed(2);var second=p.load();second.assign(71,"wind_message");second.save(p.path());p.confirmed(1);assertTrue(old.sameAs(p.load()));assertArrayEquals(original,Files.readAllBytes(p.path()));p.confirmed(2);assertEquals(71,p.load().get(0).keyCode());var reload=new NormalSpellPresets(dir);assertEquals(2,reload.preferred());assertEquals(1,reload.selected());}
 @Test void persistenceFailureStillAppliesAuthoritativeSelectionAndPreparedBindings()throws Exception{var second=new SpellKeySettings();second.assign(71,"wind_message");second.save(dir.resolve("key-settings-preset2.yml"));var p=new NormalSpellPresets(dir);p.prepare(2);Files.createDirectory(dir.resolve("normal-preset.properties"));Files.writeString(dir.resolve("normal-preset.properties/keep"),"occupied");Files.writeString(p.path(2),"invalid: [");var applied=p.confirmed(2);assertEquals(2,p.selected());assertEquals(71,applied.get(0).keyCode());assertNotNull(p.saveFailure());assertTrue(Files.exists(dir.resolve("normal-preset.properties/keep")));}
 @Test void duelAndQuidditchKeysFreezeIndependentlyOfLaterNormalPresetKeys(){var one=new SpellKeySettings();one.assign(49,"flight");one.assign(50,"wind_message");var two=new SpellKeySettings();two.assign(71,"wind_message");for(int mode:new int[]{KyudichiLoadout.KYUDICHI,KyudichiLoadout.DUEL}){var combat=new KyudichiLoadout(mode);combat.seed(java.util.List.of("wind_message","flight"));assertTrue(combat.freezeNormalKeys(one.orderedSlots(),code->false));var inherited=combat.bindings(one.orderedSlots(),code->false);assertFalse(combat.freezeNormalKeys(two.orderedSlots(),code->false));assertEquals(inherited,combat.bindings(two.orderedSlots(),code->false));}}
 @Test void cooldownIsRetainedAcrossNormalBindingsAndCombatRestore(){var s=new CastingState();s.alwaysActive();s.serverResult("hidden",1000,0);var p1=new SpellKeySettings();p1.assign(49,"flight");var combat=new SpellKeySettings();combat.assign(71,"wind_message");s.setBindings(p1);s.setBindingsDirect(combat.orderedSlots());s.setBindings(p1);assertEquals(1000,s.remaining("hidden",0));assertEquals(p1.orderedSlots(),s.bindings());assertTrue(s.enabled());s.reset();assertTrue(s.enabled());s.suspend();assertFalse(s.enabled());s.resume();assertTrue(s.enabled());}
 @Test void alwaysActiveDoesNotToggleOffAndStillRejectsGuiTyping(){var s=new CastingState();s.alwaysActive();assertEquals(CastingState.Kind.CONSUME,s.input(90,1,true,true,0,x->fail()).kind());assertTrue(s.enabled());s.releaseInputs();assertEquals(CastingState.Kind.PASS,s.input(49,1,false,false,0,x->fail()).kind());}
}
